before:
```javascript
function readWhen(flag, reader) {
  return flag && reader();
}
let calls = 0;
console.log(readWhen(0, () => ++calls));
console.log(calls);
console.log(readWhen(true, () => "ready"));
```
0; 0; ready

after:
```javascript
function readWhen(flag, reader) {
  return flag && reader();
}
let calls = 0;
console.log(readWhen(0, () => ++calls));
console.log(calls);
console.log(readWhen(true, () => "ready"));
```
Output:
```text
0
0
ready
```
The first call is skipped, so the call counter stays at 0.
